extractions = ""
for d in context:
    prompt = "You are given a single document. Your task is to extract any information about soccer/football clubs and any state/city metadata relevant to this query:\n\nQUERY CLUES:\n- We want a soccer team that was founded in the capital city of a state (as of 2016).\n- The state was established between 1985 and 1992.\n- The state has a total area between 3,800 sq. km and 5,300 sq. km (as of 2016).\n- In the 2015/16 season, the team finished with the same number of league matches won, lost, and drawn.\n- The team won its last league match of that season, which was played in October.\n\nFor this document, do the following:\n1) List any soccer/football team(s) or club(s) mentioned, giving for each:\n   - Team full name\n   - City and state/province\n   - Whether the listed city is the capital of that state (as of 2016)\n   - The state's establishment/creation date or year, if given\n   - The state's total area, if given\n   - Where and when the team was founded (city and year), if given\n   - 2015/16 season league summary (wins, draws, losses) if present; indicate explicitly if W, D, and L are equal\n   - The date and result of the last league match of the 2015/16 season; indicate if it was played in October and if it was a win\n2) If the document only contains state/city metadata (no club), still extract:\n   - State name, capital, creation year, and total area.\n3) Provide direct quotes from the document supporting each extracted fact when possible. If the document does not contain relevant information, respond with NO_RELEVANT_INFO.\n\nReturn a compact, structured summary. Avoid speculation; only use what is stated or directly inferable from this document.\n\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    result = llm_query(prompt)
    extractions = extractions + result + "\n-----\n"

final_prompt = "You are given extracted notes from multiple documents. Your job is to identify the single soccer/football team that matches ALL of the following constraints:\n- The team was founded in the capital city of a state (as of 2016).\n- The state was established between 1985 and 1992.\n- The state has a total area between 3,800 sq. km and 5,300 sq. km (as of 2016).\n- In the 2015/16 season, the team finished with the same number of league matches won, lost, and drawn.\n- The team also won its last league match of that season, which was played in October.\n\nUse only the information in the extractions below. If state metadata and club details are in different extractions, you may combine them if they clearly refer to the same state and club. If more than one team appears, choose the one that satisfies all constraints most directly and explicitly.\n\nEXTRACTIONS:\n" + extractions + "\n\nIMPORTANT: Output only the full name of the soccer team that matches, with no additional words, punctuation, or commentary."
answer = llm_query(final_prompt)
return_result(answer)